function textOf(j) {
  if (!j) return '';
  if (typeof j.mergedResponse === 'string' && j.mergedResponse) return j.mergedResponse;
  const parts = (j.content && j.content.parts) || (j.candidates && j.candidates[0] && j.candidates[0].content && j.candidates[0].content.parts);
  if (Array.isArray(parts)) return parts.map(p => p.text || '').join('');
  return typeof j.text === 'string' ? j.text : JSON.stringify(j);
}
function parseJson(t) {
  const s = String(t || '').trim().replace(/^\s*\x60\x60\x60(?:json)?/i, '').replace(/\x60\x60\x60\s*$/, '');
  const a = s.indexOf('{'); const b = s.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return {};
}
const b = $('Normalize Brief').first().json;
const d = parseJson(textOf($input.first().json));
const context = [d.campaign_name, d.big_idea, d.key_message, d.positioning].filter(Boolean).join(' | ');
const contentPlatforms = [...new Set(b.social_platforms.concat(b.ad_platforms.map(p => /meta/i.test(p) ? 'Facebook' : p)))];
return [{ json: { brief: b, director: d, run: b.run, context,
  content_input: { mode: 'plan', brand: b.brand, industry: b.industry, product: b.product, audience: b.audience, topic: d.content_topic || b.product, goal: b.objective, content_types: ['Blog post / article', 'Social media posts', 'Ad copy', 'Landing page copy'].concat(b.ai_images ? ['Visuals (AI images)'] : []), platforms: contentPlatforms, posts_count: 5, website: b.website, keywords: (d.seo_keywords || []).join(', '), tone: d.tone || 'Friendly', language: b.language, notes: 'Competitors: ' + (b.competitors || 'n/a'), campaign_context: context },
  seo_input: { mode: 'plan', website: b.website, business: b.product + ' (' + b.industry + ')', country: b.country_name, search_language: b.simple_language, keywords: (d.seo_keywords || []).join(', '), competitors: b.competitors, language: b.simple_language }
} }];

