const b = p.brief;
function first(n) { try { return $(n).first().json || {}; } catch (e) { return {}; } }
const seo = first('Run SEO Agent').seo || {};
const seoKw = [].concat(...((seo.keyword_clusters || []).filter(c => /commercial|transactional/i.test(c.intent || '')).map(c => (c.keywords || []).map(k => k.keyword)))).filter(Boolean).slice(0, 15);
const content = first('Run Content Agent').content || {};
const adCopy = (content.ad_copy || []).slice(0, 8).map(a => a.platform + ': ' + [].concat(a.headlines || []).slice(0, 3).join(' / ') + ' - ' + (a.primary_text || '')).join('\n');
return [{ json: { mode: 'plan', brand: b.brand, product: b.product, objective: b.objective, daily_budget: b.daily_budget, start_date: b.start_date, countries: b.countries.join(','), audience: b.audience, landing_url: b.landing_url, platforms: b.ad_platforms, keywords: seoKw.join(','), language: b.simple_language, notes: 'Campaign: ' + p.context + '\nDirector notes: ' + (p.director.paid_notes || '') + (adCopy ? '\nUse / adapt this approved ad copy from the content agent:\n' + adCopy : '') } }];

const p = $('Prepare Agent Inputs').first().json;
const b = p.brief;
function first(n) { try { return $(n).first().json || {}; } catch (e) { return {}; } }
const posts = ((first('Run Content Agent').content || {}).social_posts || []).filter(x => /facebook|instagram|tiktok/i.test(x.platform || '')).slice(0, 4);
const brief = posts.length ? 'Launch post for this campaign. Base it on these drafts from the content agent: ' + JSON.stringify(posts.map(x => ({ platform: x.platform, hook: x.hook, caption: x.caption, cta: x.cta }))) : 'Launch post for: ' + p.context + '. Product: ' + b.product + '. Link: ' + b.landing_url;
