const b = p.brief, d = p.director || {};
function first(n) { try { const j = $(n).first().json; return j && Object.keys(j).length ? j : null; } catch (e) { return null; } }
const content = first('Run Content Agent'), seo = first('Run SEO Agent'), paid = first('Run Paid Media Agent'), social = first('Run Social Media Agent');
function esc(v) { return String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function arr(v) { return Array.isArray(v) ? v : (v ? [v] : []); }
const box = (title, body) => '<div style="border:1px solid #e4e7ec;border-radius:10px;padding:12px;margin:10px 0"><h3 style="margin:0 0 6px;color:#3b5bdb">' + title + '</h3>' + body + '</div>';
let h = box('Campaign strategy - Marketing Director', '<p><b>' + esc(d.campaign_name) + '</b><br>' + esc(d.big_idea) + '</p><p><b>Key message:</b> ' + esc(d.key_message) + '</p>' + (arr(d.kpis).length ? '<p><b>KPIs:</b> ' + arr(d.kpis).map(k => esc(k.metric) + ' ' + esc(k.target)).join(' · ') + '</p>' : '') + (arr(d.timeline).length ? '<p><b>Timeline:</b> ' + arr(d.timeline).map(t => esc(t.week) + ': ' + esc(t.focus)).join(' | ') + '</p>' : ''));
if (content) { const c = content.content || {}; h += box('Content Creation Agent', content.error ? '<p style="color:#c4320a">' + esc(JSON.stringify(content.error)) + '</p>' : '<p>' + arr(c.social_posts).length + ' social posts · ' + arr(c.ad_copy).length + ' ad copy sets · ' + (c.blog && c.blog.title ? 'blog: <i>' + esc(c.blog.title) + '</i> · ' : '') + (c.landing_page && c.landing_page.hero_headline ? 'landing page: <i>' + esc(c.landing_page.hero_headline) + '</i>' : '') + '</p>' + arr(c.social_posts).slice(0, 3).map(x => '<p><b>' + esc(x.platform) + ':</b> ' + esc(x.hook) + ' ' + esc(String(x.caption || '').slice(0, 220)) + '</p>').join('') + '<p style="color:#667085">The full content pack is in the final download.</p>'); }
if (seo) { const s = seo.seo || {}; h += box('SEO Agent - score ' + esc(seo.seo_score) + '/100', seo.error ? '<p style="color:#c4320a">' + esc(JSON.stringify(seo.error)) + '</p>' : '<p>' + esc(seo.executive_summary) + '</p><b>Quick wins</b><ul>' + arr(s.quick_wins).slice(0, 6).map(x => '<li>' + esc(x) + '</li>').join('') + '</ul>'); }
if (paid) h += box('Paid Media Agent - media plan', paid.error ? '<p style="color:#c4320a">' + esc(JSON.stringify(paid.error)) + '</p>' : (paid.plan_html || ''));
if (social) h += box('Social Media Agent - launch post drafts', social.error ? '<p style="color:#c4320a">' + esc(JSON.stringify(social.error)) + '</p>' : (social.warnings && social.warnings.length ? '<p style="color:#b54708">' + social.warnings.map(esc).join('<br>') + '</p>' : '') + '<p>Edit the captions below before approving.</p>');
const socialLabels = social ? String(social.platform_labels || '') : '';
const paidLabels = paid ? String(paid.launch_labels || '') : '';
const actions = [].concat(social && socialLabels ? ['Publish the social posts now'] : [], paid && paidLabels ? ['Create the ad campaigns (PAUSED)'] : []);
return [{ json: { summary_html: h, social_labels: socialLabels, paid_labels: paidLabels, actions_default: actions.join(','), facebook_caption: social ? social.facebook_caption || '' : '', instagram_caption: social ? social.instagram_caption || '' : '', tiktok_caption: social ? social.tiktok_caption || '' : '' } }];

const b = $('Prepare Agent Inputs').first().json.brief;
const f = $('Approve Execution').first().json;
const s = $('Run Social Media Agent').first().json;
return [{ json: { mode: 'execute', platforms: String(s.platform_labels || '').split(',').filter(Boolean), media_type: b.media_type, media_url: b.media_url, link: b.landing_url, publish_when: 'now', language: b.language, captions: { facebook: f.facebook_caption, instagram: f.instagram_caption, tiktok: f.tiktok_caption } } }];

const base = $('Paid Media Input').first().json;
const f = $('Approve Execution').first().json;
const plan = $('Run Paid Media Agent').first().json.plan;
return [{ json: Object.assign({}, base, { mode: 'execute', plan, approved_platforms: [].concat(f.paid_platforms || []) }) }];

const p = $('Prepare Agent Inputs').first().json;
const center = $('Build Command Center').first().json;
function first(n) { try { const j = $(n).first().json; return j && Object.keys(j).length ? j : null; } catch (e) { return null; } }
function esc(v) { return String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
const color = s => /fail/.test(s) ? '#c4320a' : /(published|created|sent)/.test(s) ? '#12805c' : '#667085';
const rows = [];
const soc = first('Publish via Social Media Agent'); if (soc) (soc.results || []).forEach(r => rows.push(Object.assign({ agent: 'Social' }, r)));
const pd = first('Launch via Paid Media Agent'); if (pd) (pd.results || []).forEach(r => rows.push(Object.assign({ agent: 'Paid' }, r)));
const exec = rows.length ? '<div style="border:2px solid #3b5bdb;border-radius:10px;padding:12px;margin:10px 0"><h3 style="margin:0 0 6px">Execution results</h3>' + rows.map(r => '<p><b>' + esc(r.agent) + ' · ' + esc(r.platform) + '</b> <span style="color:#fff;background:' + color(r.status) + ';border-radius:99px;padding:1px 9px;font-size:12px">' + esc(r.status) + '</span><br>' + esc(r.detail) + '</p>').join('') + '</div>' : '<p><b>Nothing was executed - report only.</b></p>';
let extra = '';
const seo = first('Run SEO Agent'); if (seo && seo.html) extra += '<h2>Full SEO report</h2><iframe style="width:100%;height:900px;border:1px solid #e4e7ec;border-radius:10px" srcdoc="' + String(seo.html).replace(/&/g, '&amp;').replace(/"/g, '&quot;') + '"></iframe>';
const c = first('Run Content Agent');
const ar = /Arabic/.test(p.brief.language);
const html = '<!DOCTYPE html><html lang="' + (ar ? 'ar' : 'en') + '" dir="' + (ar ? 'rtl' : 'ltr') + '"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Command Center - ' + esc(p.brief.brand) + '</title></head><body style="font:15px/1.6 system-ui,Segoe UI,Tahoma,sans-serif;background:#f6f7fb;color:#1d2433;margin:0"><div style="max-width:1100px;margin:0 auto;padding:24px 16px"><h1>Marketing Command Center: ' + esc(p.brief.brand) + '</h1><p style="color:#667085">' + $now.toFormat('yyyy-MM-dd HH:mm') + '</p>' + exec + '<div style="background:#fff;border:1px solid #e4e7ec;border-radius:12px;padding:16px">' + center.summary_html + '</div>' + (c && c.content ? '<h2>Content pack</h2><p>' + esc(c.big_idea) + '</p><pre style="white-space:pre-wrap;background:#fff;border:1px solid #e4e7ec;border-radius:10px;padding:12px;font-size:13px">' + esc(JSON.stringify(c.content, null, 2)).slice(0, 60000) + '</pre>' : '') + extra + '</div></body></html>';
const fileName = 'command-center-' + (String(p.brief.brand || 'brand').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'brand') + '-' + $now.toFormat('yyyyMMdd-HHmm') + '.html';
return [{ json: { results: rows, file_name: fileName }, binary: { data: await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), fileName, 'text/html') } }];

const b = $('Normalize Brief').first().json;
return [{ json: {
  company: b.brand, industry: b.industry, competitors: b.competitors, fb_pages: '', tiktok_keywords: '',
  ads_country: b.countries[0] || 'ALL', region: b.country_name, target_customers: b.audience,
  focus: 'Product / offer: ' + b.product + '. Campaign objective: ' + b.objective,
  language: b.simple_language
} }];

const b = $('Normalize Brief').first().json;
const ch = new Set();
b.social_platforms.concat(b.ad_platforms).forEach(p => {
  if (/facebook|instagram|meta/i.test(p)) ch.add('Meta (Facebook & Instagram)');
  else if (/tiktok/i.test(p)) ch.add('TikTok');
  else if (/snap/i.test(p)) ch.add('Snapchat');
  else if (/google/i.test(p)) ch.add('Google Search');
});
if (b.website) ch.add('SEO & Content');
ch.add('Email / CRM'); ch.add('WhatsApp');
const obj = { Awareness: 'Brand awareness', Engagement: 'Brand awareness', Traffic: 'Brand awareness', Leads: 'Lead generation', Sales: 'Sales / revenue' };
return [{ json: {
  brand_name: b.brand, industry: b.industry, product_description: b.product, target_market: b.countries.join(', ') + ' (' + b.country_name + ')',
  target_audience: b.audience, objectives: [obj[b.objective] || b.objective], goal_target: '',
  total_budget: (b.daily_budget || 0) * 30, currency: b.currency, start_date: b.start_date, duration_months: '1',
  usp: '', competitors: b.competitors, available_channels: Array.from(ch), brand_tone: 'Friendly',
  output_language: b.simple_language === 'English' ? 'English' : 'العربية',
  extra_notes: 'Generated by the Marketing Command Center (full cycle). Budget = daily ads budget x 30 days.',
  meta_ad_account_id: '', tiktok_advertiser_id: '', competitor_facebook_pages: '', competitor_tiktok_handles: '', trend_keywords: ''
} }];

const b = $('Normalize Brief').first().json;
function all(n) { try { return $(n).all().map(i => i.json); } catch (e) { return []; } }
const s = all('Get Latest Strategy').find(r => r && r.executive_summary);
const cut = (v, n) => String(v || '').slice(0, n);
const strategy_context = s ? 'Plan date: ' + (s.createdAt || '') + '\nExecutive summary: ' + cut(s.executive_summary, 1500) + '\nPositioning: ' + cut(s.positioning_statement, 800) + '\nKey messages: ' + cut(s.key_messages, 3000) + '\nChannel mix: ' + cut(s.channel_mix, 3000) + '\nCampaigns: ' + cut(s.campaigns, 3000) + '\nKPIs: ' + cut(s.kpis, 2000) : 'No saved strategic plan for this brand - build the campaign from the brief and your research.';
const rows = all('Get Planning Learnings').filter(r => r && (r.summary || r.learnings));
const learnings_context = rows.length ? rows.map(r => '- Week ' + (r.week || '') + ' (ROAS ' + (r.roas == null ? 'n/a' : r.roas) + '): ' + cut(r.summary, 400) + ' | Learnings: ' + cut(r.learnings, 1200) + ' | Recommendations: ' + cut(r.recommendations, 800)).join('\n') : 'No past performance learnings yet.';
return [{ json: { ...b, strategy_context, learnings_context, has_strategy: !!s } }];

