const box = '<div style="border:2px solid ' + color + ';border-radius:10px;padding:12px;margin:10px 0"><h3 style="margin:0 0 6px;color:' + color + '">Governance - Brand &amp; Compliance: ' + esc(String(c.status || 'review').toUpperCase()) + (c.score ? ' (' + esc(c.score) + '/100)' : '') + '</h3>' + (c.status === 'fail' ? '<p><b>Execution is un-ticked by default. Fix the issues below before approving.</b></p>' : '') + list('Brand', c.brand_issues) + list('Legal &amp; privacy', c.legal_privacy_issues) + list('Platform policies', c.platform_policy_issues) + list('Reputation', c.reputation_risks) + list('Suggested fixes', c.fixes) + '</div>';
return [{ json: { ...base, summary_html: box + base.summary_html, actions_default: c.status === 'fail' ? '' : base.actions_default, compliance: c } }];
